        text: 'ESPOO, Finland — European microsatellite leader ICEYE unveiled its Gen5 Synthetic Aperture Radar (SAR) satellite system on November 16, achieving commercial imagery resolutions down to 11 centimeters paired with onboard artificial intelligence chips that process maritime, disaster, and security telemetry directly in orbit.',
        text_bn: 'এস্পো, ফিনল্যান্ড — ইউরোপীয় মহাকাশ প্রযুক্তি প্রতিষ্ঠান আইসআই ১৬ নভেম্বর তাদের পঞ্চম প্রজন্মের ‘জেন৫’ সিনথেটিক অ্যাপারচার রাডার (SAR) স্যাটেলাইট সিস্টেম উন্মোচন করেছে। ১১ সেন্টিমিটার পর্যন্ত সূক্ষ্ম রেজল্যুশনের পাশাপাশি এর অন-বোর্ড এআই সরাসরি কক্ষপথেই দুর্যোগ ও সামুদ্রিক তথ্য বিশ্লেষণ করতে পারে।',
