      thumbnailUrl: 'https://images.unsplash.com/photo-1517154421773-0529f29ea451?auto=format&fit=crop&w=400&q=80',
      filename: 'seoul_south_korea_semiconductor_ai_2026.jpg',
      sizeBytes: 2580000,
      caption: 'Seoul and the Gyeonggi semiconductor belt anchor South Korea’s next-generation memory and sovereign AI infrastructure.',
      caption_bn: 'সিউল ও গিয়ংগি সেমিকন্ডাক্টর বলয় দক্ষিণ কোরিয়ার পরবর্তী প্রজন্মের মেমোরি ও সার্বভৌম এআই অবকাঠামোর কেন্দ্র হয়ে উঠেছে।',
      credit: 'Meridian Seoul Bureau',
      uploadedAt: '2026-11-16T02:18:00Z',
