    blocks: [
      {
        id: 'b-57-1',
        type: 'paragraph',
        text: 'SEOUL / YONGIN — South Korean memory giant SK Hynix unveiled a five-year ₩1.4 trillion ($1.05 billion) domestic semiconductor ecosystem investment plan on November 16, expanding its Yongin cluster’s Trinity Fab to let Korean equipment and materials suppliers run live 12-inch wafer verification tests.',
        text_bn: 'সিউল / ইয়ংগিন — দক্ষিণ কোরিয়ার চিপ নির্মাতা এসকে হাইনিক্স ১৬ নভেম্বর আগামী পাঁচ বছরে দেশীয় সেমিকন্ডাক্টর সরঞ্জাম ও উপকরণ সরবরাহকারীদের জন্য ১.৪ ট্রিলিয়ন ওন (প্রায় ১.০৫ বিলিয়ন ডলার) বিনিয়োগের ঘোষণা দিয়েছে, যার কেন্দ্রে রয়েছে ইয়ংগিনের ‘ট্রিনিটি ফ্যাব’ ১২-ইঞ্চি ওয়েফার পরীক্ষাগার।',
      },
      {
        id: 'b-57-2',
        type: 'paragraph',
        text: 'Separately, Nvidia reaffirmed plans to supply more than 260,000 advanced GPUs to South Korea’s government and industrial champions—including Samsung Electronics, SK Group, Hyundai Motor, and Naver—to accelerate sovereign AI data centers, autonomous factories, and physical robotics models.',
        text_bn: 'অন্যদিকে, দক্ষিণ কোরিয়ার সরকার ও শীর্ষ শিল্পগোষ্ঠী—স্যামসাং ইলেকট্রনিক্স, এসকে গ্রুপ, হুন্দাই মোটর ও নাভারের—জন্য ২৬০,০০০-এর বেশি উন্নত জিপিইউ সরবরাহের প্রতিশ্রুতি পুনর্ব্যক্ত করেছে এনভিডিয়া, যা দেশটির সার্বভৌম এআই ডেটা সেন্টার ও রোবটিক্স খাতকে ত্বরান্বিত করবে।',
      },
      {
        id: 'b-57-3',
        type: 'paragraph',
        text: 'Meanwhile, South Korea’s Ministry of Employment and Labor ordered an emergency security audit across all 2026 national qualification exams after Seoul Metropolitan Police opened an investigation into a top-scoring tax accountant candidate who confessed to using a miniature camera and generative AI during April and July exam sittings.',
        text_bn: 'এদিকে, জাতীয় কর হিসাবরক্ষক পরীক্ষায় শীর্ষ নম্বর পাওয়া এক প্রার্থী গোপন ক্ষুদ্র ক্যামেরা ও জেনারেটিভ এআই ব্যবহার করে নকলের কথা স্বীকার করার পর সিউল মেট্রোপলিটন পুলিশ তদন্ত শুরু করেছে এবং ২০২৬ সালের সব জাতীয় যোগ্যতা পরীক্ষায় জরুরি নিরাপত্তা অডিটের নির্দেশ দিয়েছে শ্রম মন্ত্রণালয়।',
      },
    ],
