    slug: 'japan-q3-gdp-contraction-yen-160-threshold-defense-ai-guidelines-2026',
    title: 'Japan Economy Contracts 0.1% in Q3 as Tokyo Watches ¥160/$ Currency Threshold and Prepares Defense AI Rules',
    title_bn: 'তৃতীয় প্রান্তিকে জাপানের অর্থনীতিতে ০.১% সংকোচন: ইয়েনের মান ১৬০ ছাড়ানোর সতর্কতা ও প্রতিরক্ষা এআই নীতিমালা প্রস্তুত করছে টোকিও',
    summary: 'Cabinet Office figures show unexpected July–September contraction driven by weaker household spending, while Finance Minister Satsuki Katayama warns on yen intervention and Defense Minister Shinjiro Koizumi readies end-November Defense AI Guidelines.',
    summary_bn: 'মূল্যস্ফীতি ও টাইফুনের প্রভাবে পারিবারিক ব্যয় কমায় তৃতীয় প্রান্তিকে জাপানের জিডিপি ০.১% সংকুচিত হয়েছে; ইয়েনের বিনিময় হার ১৬০ ছাড়ানোয় অর্থমন্ত্রী সাতসুকি কাতায়ামা সতর্কবার্তা দিয়েছেন এবং নভেম্বরের শেষে প্রতিরক্ষা এআই নীতিমালা প্রকাশ করবেন মন্ত্রী শিনজিরো কোইজুমি।',
