      caption: 'Tokyo financial districts closely monitor Bank of Japan policy and yen intervention risks after Q3 GDP figures.',
      caption_bn: 'তৃতীয় প্রান্তিকের জিডিপি তথ্যের পর ব্যাংক অব জাপানের নীতি ও ইয়েনের দরপতন মোকাবিলায় নজর রাখছে টোকিওর আর্থিক বাজার।',
      credit: 'Meridian Tokyo Bureau',
      uploadedAt: '2026-11-16T02:14:00Z',
