        id: 'b-59-1',
        type: 'paragraph',
        text: 'SEOUL / BEIJING — South Korean Foreign Minister Cho Hyun held high-level consultations with Chinese counterpart Wang Yi in Beijing ahead of regional APEC diplomacy, pressing for constructive engagement to safeguard stability on the Korean Peninsula and protect East Asian supply chains.',
        text_bn: 'সিউল / বেইজিং — আঞ্চলিক অ্যাপেক কূটনৈতিক সম্মেলনের আগে বেইজিংয়ে চীনের পররাষ্ট্রমন্ত্রী ওয়াং ই-এর সঙ্গে উচ্চপর্যায়ের বৈঠক করেছেন দক্ষিণ কোরিয়ার পররাষ্ট্রমন্ত্রী চো হিউন। বৈঠকে কোরীয় উপদ্বীপে শান্তি ও পূর্ব এশিয়ার সরবরাহ শৃঙ্খল সুরক্ষায় কার্যকর সহযোগিতার আহ্বান জানানো হয়।',
