        type: 'paragraph',
        text: 'SEOUL — A longtime stall owner in Seoul’s historic Namdaemun Market—nicknamed the “Scarf Man” online—has become an unexpected global sensation after videos of his playful reverse-psychology sales pitch telling passersby “Do not buy! Just look!” racked up tens of millions of views across Asia, Europe, and North America.',
        text_bn: 'সিউল — সিউলের ঐতিহাসিক নামদেমুন বাজারের দীর্ঘদিনের এক স্কার্ফ বিক্রেতা ‘স্কার্ফ ম্যান’ হিসেবে বিশ্বব্যাপী সামাজিক মাধ্যমে ভাইরাল হয়েছেন। পথচারীদের মজা করে “কিনবেন না, শুধু দেখুন!” বলার অভিনব কৌশলের ভিডিও এশিয়া, ইউরোপ ও উত্তর আমেরিকায় কোটি কোটি ভিউ পেয়েছে।',
