        text: 'Tourism boards in both South Korea and Japan report brisk late-autumn visitor growth along the Seoul–Busan–Tokyo–Kyoto corridor, buoyed by K-culture exhibitions, winter craft markets, and renewed appetite for heritage street districts and regional cinema.',
