        text: 'BRUSSELS / KYIV — Anxiety over a potential "Yalta 2.0" carving of spheres of influence has galvanized European governments ahead of the November 19 Trump-Xi-Putin summit in Shenzhen, even after the White House emphasized that the Russia-Ukraine war is excluded from the trilateral agenda.',
