        text_bn: 'মহাকাশ গবেষণায় একাধিক যুগান্তকারী সাফল্যের মধ্যেই এই মাইলফলক এলো: ডার্পার এনওএম৪ডি কর্মসূচির সহায়তায় ক্যালটেকের গবেষকরা নভোচারীর সাহায্য ছাড়াই মহাকাশে প্রথম স্বয়ংক্রিয় রোবোটিক কাঠামো নির্মাণ প্রদর্শন করেছেন, আর এমআইটি ও হার্ভার্ডের বিজ্ঞানীরা প্রারম্ভিক মহাবিশ্বের ২০০ কোটি বছরের ইতিহাস পুনর্গঠনে ‘লুমিনা’ সুপারকম্পিউটার সিমুলেশন উন্মোচন করেছেন।',
