        text: 'GENEVA — Marking World Prematurity Day on November 15, 2026, the World Health Organization (WHO) issued an urgent call to expand neonatal intensive care unit (NICU) access and multi-year developmental follow-up for the estimated 15 million infants born prematurely each year worldwide.',
