        text: 'LONDON — Fresh commercial satellite imagery reviewed by defense verification teams indicates rapid repair and fortification work across Iranian missile and military compounds—including Garmdareh, Shahroud, and Parchin—months after prior regional strikes inflicted extensive structural damage.',
        text_bn: 'লন্ডন — আন্তর্জাতিক প্রতিরক্ষা বিশ্লেষকদের পর্যালোচনাকৃত নতুন বাণিজ্যিক স্যাটেলাইট চিত্রে দেখা গেছে, পূর্ববর্তী হামলায় ব্যাপক ক্ষতির পর ইরান তার গার্মদারেহ, শাহরুদ ও পারচিন ক্ষেপণাস্ত্র ও সামরিক কমপ্লেক্সগুলোতে দ্রুত পুনর্নির্মাণ ও সুরক্ষা কাজ জোরদার করেছে।',
