        text: 'TASHKENT / BRUSSELS — As trade barriers, sanctions, and maritime bottlenecks reshape 2026 global commerce, Central Asia has quietly evolved from a landlocked periphery into one of Eurasia’s fastest-growing logistics and critical-minerals bridges.',
        text_bn: 'তাশখন্দ / ব্রাসেলস — ২০২৬ সালে বাণিজ্যিক নিষেধাজ্ঞা ও সমুদ্রপথের ঝুঁকি বাড়ার সাথে সাথে স্থলবেষ্টিত মধ্য এশিয়া নীরবে চীন ও ইউরোপের মধ্যকার অন্যতম দ্রুত বর্ধনশীল লজিস্টিকস এবং কৌশলগত খনিজ বাণিজ্যের সেতুবন্ধনে পরিণত হয়েছে।',
