        text: 'GOA — Organizers of the 57th International Film Festival of India (IFFI) finalized the global slate ahead of the November 20 opening, curating 159 films from 86 countries under the unifying banner "Stories Without Borders."',
        text_bn: 'গোয়া — আগামী ২০ নভেম্বর শুরু হতে যাওয়া ৫৭তম আন্তর্জাতিক চলচ্চিত্র উৎসবের (ইফি) চূড়ান্ত তালিকা প্রকাশ করা হয়েছে। ‘সীমান্তহীন গল্প’ প্রতিপাদ্যে এবারের আসরে ৮৬টি দেশের ১৫৯টি চলচ্চিত্র প্রদর্শিত হবে।',
