      caption: 'Deep-water offshore wind arrays feeding the newly commissioned 18-gigawatt North Sea energy island.',
      caption_bn: 'উত্তর সাগরে স্থাপিত ১৮ গিগাওয়াট ক্ষমতাসম্পন্ন অফশোর বায়ুবিদ্যুৎ কেন্দ্রের টারবাইন সারি।',
      credit: 'Nordic Grid Media / Meridian Photo',
