    title: 'UN Security Council and Global Envoys Finalize Historic Middle East Peace and Reconstruction Accord in Geneva',
    title_bn: 'জেনেভায় জাতিসংঘ ও বৈশ্বিক দূতদের মধ্যস্থতায় ঐতিহাসিক মধ্যপ্রাচ্য শান্তি ও টেকসই পুনর্গঠন চুক্তি চূড়ান্ত',
    summary: 'Multilateral peace negotiators in Geneva approve comprehensive reconstruction framework backed by $65 billion humanitarian stabilization pledges and permanent border monitoring protocols.',
    summary_bn: 'জেনেভায় বহুপাক্ষিক শান্তি আলোচনায় স্থায়ী যুদ্ধবিরতি ও ৬৫ বিলিয়ন ডলারের মানবিক পুনর্গঠন তহবিল অনুমোদিত হয়েছে, যা আন্তর্জাতিক শান্তিরক্ষীদের নিরপেক্ষ তত্ত্বাবধানে বাস্তবায়িত হবে।',
    category: 'World',
