    title: 'Global Climate Summit in Nairobi Finalizes Landmark $100B Loss and Damage Operationalization Compact',
    title_bn: 'নাইরোবিতে বিশ্ব জলবায়ু সম্মেলনে ১০০ বিলিয়ন ডলারের ক্ষতিপূরণ তহবিল চুক্তি চূড়ান্ত',
    summary: 'Envoys from 140 nations establish expedited disbursement mechanisms for coastal and agricultural economies facing extreme weather shocks, with initial capitalization unlocked immediately.',
    summary_bn: 'চরম আবহাওয়া বিপর্যয়ের শিকার দেশগুলোর জন্য ১০০ বিলিয়ন ডলারের ক্ষতিপূরণ তহবিল দ্রুত ছাড়ের ঐতিহাসিক রূপরেখা অনুমোদন করেছে ১৪০টি দেশ, যা অবিলম্বে কার্যকর হচ্ছে।',
