      caption: 'Delegates rise to applaud unanimous ratification of the Nairobi Climate Compensation Compact.',
      caption_bn: 'নাইরোবি জলবায়ু ক্ষতিপূরণ চুক্তি সর্বসম্মতিক্রমে অনুমোদনের পর প্রতিনিধি দলের করতালি।',
