        text_bn: 'ভিয়েনা — ওয়ার্ল্ড অ্যাথলেটিকস শুক্রবার আনুষ্ঠানিকভাবে স্বীকৃতি দিয়েছে যে উন্মুক্ত প্রতিযোগিতামূলক ম্যারাথনে ইতিহাসের প্রথমবার ২ ঘণ্টার বাধা অতিক্রম করা হয়েছে। ভিয়েনা শরৎকালীন ম্যারাথনে ১ ঘণ্টা ৫৯ মিনিট ১৪ সেকেন্ডের সময়কে নতুন বিশ্বরেকর্ড হিসেবে অনুমোদন দেওয়া হয়।',
