        type: 'paragraph',
        text: 'DRESDEN — Industrial leaders from Germany, the Netherlands, Japan, and South Korea formally launched construction on Tuesday of the continent’s most advanced photonic foundry, an investment totaling €26.2 billion ($28.4 billion) backed by European Chips Act capital and private equity syndicates.',
        text_bn: 'ড্রেসডেন — ইউরোপীয় চিপস অ্যাক্ট এবং আন্তর্জাতিক বিনিয়োগের যৌথ সহযোগিতায় জার্মানি, নেদারল্যান্ডস, জাপান এবং দক্ষিণ কোরিয়ার শীর্ষ প্রযুক্তিবিদরা মঙ্গলবার মহাদেশের সর্বাধুনিক ফোটোনিক চিপ কারখানা নির্মাণের আনুষ্ঠানিক সূচনা করেছেন। মোট বিনিয়োগের পরিমাণ ২৮.৪ বিলিয়ন ডলার।',
